/**
 * Invitation tokens (P2.3). The token is generated by the DATABASE (32 random bytes) and returned once to the inviter's server
 * action; only its SHA-256 hash is stored (private.organization_invite_secrets.token_hash, bytea 32). The application never
 * stores, logs or re-derives a token. This module only validates the shape of a token received from a link and builds/redacts
 * links. Pure module.
 *
 * Encoding: base64url without padding, exactly 43 characters (32 bytes).
 */
export const INVITE_TOKEN_LENGTH = 43;
const INVITE_TOKEN_RE = /^[A-Za-z0-9_-]{43}$/;

export const isWellFormedInviteToken = (value: unknown): value is string => typeof value === 'string' && INVITE_TOKEN_RE.test(value);

/** Where the invitation link points. Query (not fragment) so a server action can read it; the page strips it from the URL. */
export const INVITE_ACCEPT_PATH = '/invite/accept';

/** Builds the one-time acceptance link. The base must be an https origin (http only for localhost development). */
export function buildInviteAcceptLink(baseUrl: string, token: string): string {
  if (!isWellFormedInviteToken(token)) throw new Error('invalid invitation token');
  let base: URL;
  try {
    base = new URL(baseUrl);
  } catch {
    throw new Error('invalid base url');
  }
  const localDev = base.protocol === 'http:' && (base.hostname === 'localhost' || base.hostname === '127.0.0.1');
  if (base.protocol !== 'https:' && !localDev) throw new Error('invitation links must use https');
  if (base.username || base.password) throw new Error('invalid base url');
  const url = new URL(INVITE_ACCEPT_PATH, base.origin);
  url.searchParams.set('token', token);
  return url.toString();
}

/** For logs and error reports: removes the token from any string that may contain a link or the raw token. */
export function redactInviteToken(text: string): string {
  return text.replace(/([?&]token=)[A-Za-z0-9_-]+/gi, '$1<redacted>').replace(/\b[A-Za-z0-9_-]{43}\b/g, '<redacted-token>');
}
